   486  struct NoncontextualSubtable
   487  {
   488    inline bool apply (hb_aat_apply_context_t *c) const
   489    {
   490      TRACE_APPLY (this);
   491
   492      bool ret = false;
   493      unsigned int num_glyphs = c->face->get_num_glyphs ();
   494
   495      hb_glyph_info_t *info = c->buffer->info;
   496      unsigned int count = c->buffer->len;
   497      for (unsigned int i = 0; i < count; i++)
   498      {
   499        const GlyphID *replacement = substitute.get_value (info[i].codepoint, num_glyphs);
   500        if (replacement)
   501        {
   502          info[i].codepoint = *replacement;
   503          ret = true;
   504        }
   505      }
   506
   507      return_trace (ret);
   508    }
   509
   510    inline bool sanitize (hb_sanitize_context_t *c) const
   511    {
   512      TRACE_SANITIZE (this);
   513      return_trace (substitute.sanitize (c));
   514    }
   515
   516    protected:
   517    Lookup<GlyphID>       substitute;
   518    public:
   519    DEFINE_SIZE_MIN (2);
   520  };
